/* Device-selected files are kept temporarily in memory and are never saved with records. */
const attachmentModules=['parts','jobs','sales','purchases','insurance','expenses','staff'];
const temporaryAttachmentFiles=new Map();
const temporaryAttachmentNotes=new Map();
let removedOldAttachments=false;for(let key of attachmentModules)for(let record of(db[key]||[]))if(record.attachments?.length){delete record.attachments;removedOldAttachments=true}if(Array.isArray(db.attachments)&&db.attachments.length){db.attachments=[];removedOldAttachments=true}if(removedOldAttachments)save('Old saved attachments removed; new files are temporary');

function temporaryShareFilesFor(record){return record?temporaryAttachmentFiles.get((record._module||'')+'|'+record.id)||[]:[]}
function attachmentFiles(record){return []}
function safeAttachment(file){return typeof File!=='undefined'&&file instanceof File}
function attachmentPanel(key,id){let r=find(key,id);if(!r)return '';let storageKey=key+'|'+id,files=temporaryAttachmentFiles.get(storageKey)||[],notes=temporaryAttachmentNotes.get(storageKey)||'';return `<section class="attachmentPanel" data-attachment-key="${key}" data-attachment-id="${esc(id)}"><h3>${key==='insurance'?'Insurance Policy Documents & Images':'Documents & Images'} (${files.length})</h3><p>Select files from this PC or phone, capture a document with the device camera, and add a short note for each upload group. Files stay in this tab temporarily and are not saved with the record. PDF, images and videos · up to 10 files · 50 MB each.</p><div class="attachmentUploadActions"><label class="btn secondary">📎 Attach from PC / Phone<input type="file" data-attachment-upload multiple accept="application/pdf,image/jpeg,image/png,image/webp,video/mp4,video/webm,video/quicktime" aria-label="Attach files from PC or phone"></label><label class="btn secondary attachmentCameraButton">📷 Camera / Scan Document<input type="file" data-attachment-upload accept="image/jpeg,image/png,image/webp" capture="environment" aria-label="Capture or scan a document with the device camera"></label></div><label class="field attachmentNotesField"><span>Document notes</span><textarea data-attachment-notes rows="2" placeholder="Optional note about these documents..."></textarea></label><div class="attachmentFiles">${files.map((f,i)=>`<div class="attachmentFile"><span class="attachmentPdf">${f.type.startsWith('video/')?'VIDEO':f.type.startsWith('image/')?'IMAGE':'PDF'}</span><span><strong>${esc(f.name)}</strong><small>${Math.ceil(f.size/1024)} KB · temporary</small></span><button type="button" class="btn danger small" data-attachment-remove="${i}">Remove</button></div>`).join('')||'<p>No temporary files selected.</p>'}</div></section>`}
function manageAttachments(key,id){openModal('Documents & Images',`<div class="formbody">${attachmentPanel(key,id)}</div><div class="formactions">${btn('Close','cancel','secondary')}</div>`)}
function refreshAttachmentPanel(panel,key,id){let temp=document.createElement('div');temp.innerHTML=attachmentPanel(key,id);let next=temp.firstElementChild;let notes=temporaryAttachmentNotes.get(key+'|'+id)||'';let noteField=next.querySelector('[data-attachment-notes]');if(noteField)noteField.value=notes;panel.replaceWith(next)}
async function readAttachment(file){if(file.size>1024*1024)throw Error(file.name+': maximum file size is 1 MB');let bytes=new Uint8Array(await file.arrayBuffer()),type='';if(bytes[0]===137&&bytes[1]===80&&bytes[2]===78&&bytes[3]===71)type='image/png';else if(bytes[0]===255&&bytes[1]===216&&bytes[2]===255)type='image/jpeg';else if(String.fromCharCode(...bytes.slice(0,4))==='RIFF'&&String.fromCharCode(...bytes.slice(8,12))==='WEBP')type='image/webp';else if(String.fromCharCode(...bytes.slice(0,5))==='%PDF-')type='application/pdf';if(!type)throw Error(file.name+': only PDF, JPG, PNG and WebP files are supported');let data=await new Promise((resolve,reject)=>{let reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Unable to read '+file.name));reader.readAsDataURL(new Blob([bytes],{type}))});return {name:file.name,size:file.size,type,data,uploadedAt:new Date().toISOString()}}
function commitAttachments(key,id,files){temporaryAttachmentFiles.set(key+'|'+id,files)}
document.addEventListener('change',e=>{if(!e.target.matches('[data-attachment-upload]'))return;let panel=e.target.closest('[data-attachment-key]'),key=panel.dataset.attachmentKey,id=panel.dataset.attachmentId,input=e.target;try{let files=Array.from(input.files||[]),previous=temporaryAttachmentFiles.get(key+'|'+id)||[],all=[...previous,...files];if(all.length>10)throw Error('Choose up to 10 files');let total=0;for(let file of all){if(!['application/pdf','image/jpeg','image/png','image/webp','video/mp4','video/webm','video/quicktime'].includes(file.type))throw Error(file.name+': choose PDF, JPG, PNG, WebP, MP4, WebM or MOV');if(file.size>50*1024*1024)throw Error(file.name+': maximum 50 MB');total+=file.size}if(total>100*1024*1024)throw Error('Selected files must total no more than 100 MB');temporaryAttachmentFiles.set(key+'|'+id,all);if(panel.isConnected)refreshAttachmentPanel(panel,key,id)}catch(err){toast(err.message)}finally{input.value=''}},true);
document.addEventListener('input',e=>{if(!e.target.matches('[data-attachment-notes]'))return;let panel=e.target.closest('[data-attachment-key]');if(panel)temporaryAttachmentNotes.set(panel.dataset.attachmentKey+'|'+panel.dataset.attachmentId,e.target.value)},true);
document.addEventListener('click',e=>{let manager=e.target.closest('[data-manage-attachments]');if(manager){e.preventDefault();let [key,id]=manager.dataset.manageAttachments.split('|');manageAttachments(key,id);return}let button=e.target.closest('[data-attachment-remove],[data-attachment-view]');if(!button)return;e.preventDefault();let panel=button.closest('[data-attachment-key]'),key=panel.dataset.attachmentKey,id=panel.dataset.attachmentId,files=temporaryAttachmentFiles.get(key+'|'+id)||[],index=Number(button.dataset.attachmentRemove??button.dataset.attachmentView),file=files[index];if(button.hasAttribute('data-attachment-remove')){temporaryAttachmentFiles.set(key+'|'+id,files.filter((_,i)=>i!==index));refreshAttachmentPanel(panel,key,id)}else if(file instanceof File){let url=URL.createObjectURL(file),viewer=document.createElement('div');viewer.className='attachmentViewer';viewer.innerHTML=`<button type="button" class="btn secondary">Close Preview</button>${file.type==='application/pdf'?'<iframe title="Document preview" sandbox></iframe>':file.type.startsWith('video/')?'<video controls style="max-width:100%;max-height:80vh"></video>':'<img alt="Attachment preview">'}`;let media=viewer.querySelector('iframe,video,img');media.src=url;viewer.querySelector('button').onclick=()=>{URL.revokeObjectURL(url);viewer.remove()};document.body.appendChild(viewer)}},true);
const renderBeforeAttachments=render;
render=function(){renderBeforeAttachments()};
function addFormAttachments(key,id){if(!attachmentModules.includes(key))return;let form=$('#recordForm')||$('#billForm'),body=form?.querySelector('.formbody');if(!body)return;if(id&&find(key,id))body.insertAdjacentHTML('beforeend',attachmentPanel(key,id));else body.insertAdjacentHTML('beforeend','<div class="notice">Save this new record first, then use Documents & Images to upload attachments.</div>')}
const editBeforeAttachments=editRecord;
editRecord=function(key,id,initial){editBeforeAttachments(key,id,initial);if(!['jobs','sales','purchases'].includes(key))addFormAttachments(key,id)};
const billBeforeAttachments=billForm;
billForm=function(key,id,initial){billBeforeAttachments(key,id,initial);addFormAttachments(key,id)};
render();

