function receiptRows(b){return [...(b.partLines||[]).map(l=>({name:l.name||name('parts',l.part),qty:Number(l.qty||0),rate:Number(l.price||0),amount:round(Number(l.qty||0)*Number(l.price||0)*(1+Number(b.invoiceType==='non-gst'?0:l.gst||0)/100))})),...(b.serviceLines||[]).map(l=>({name:l.name||name('services',l.service),qty:1,rate:Number(l.charge||0),amount:Number(l.charge||0)}))]}
function receiptCanvas(key,id){let b=find(key,id);if(!b)throw Error('Invoice not found');let c=find('customers',b.customer),rows=receiptRows(b),t=billTotals(b),canvas=document.createElement('canvas');canvas.width=1000;let measure=canvas.getContext('2d');measure.font='20px Arial';function wrap(text,width){let lines=[],line='';for(let word of String(text||'').split(/\s+/)){if(measure.measureText(line+' '+word).width>width&&line){lines.push(line);line=word}else line+=(line?' ':'')+word}lines.push(line);return lines}let heights=rows.map(r=>Math.max(52,wrap(r.name,460).length*27+20));canvas.height=720+heights.reduce((s,n)=>s+n,0)+240;let x=canvas.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,1000,canvas.height);function text(value,left,top,size=20,bold=false,color='#111827'){x.font=(bold?'bold ':'')+size+'px Arial';x.fillStyle=color;x.fillText(String(value??''),left,top)}function rule(y){x.strokeStyle='#cbd5e1';x.beginPath();x.moveTo(35,y);x.lineTo(965,y);x.stroke()}text(invoiceTypeOf(b)==='gst'?'GST TAX INVOICE':'NON-GST INVOICE',35,48,24,true);text(db.settings.name,35,92,32,true);let address=wrap(db.settings.address||'',900);address.slice(0,2).forEach((v,i)=>text(v,35,125+i*25,18));text('Phone: '+(db.settings.phone||'—')+(invoiceTypeOf(b)==='gst'?'   GSTIN: '+(db.settings.gst||'—'):''),35,185,18);rule(207);text('Invoice / Job Card: '+(b.sourceId||b.id),35,240,21,true);text('Date: '+(typeof displayDate==='function'?displayDate(b.date):b.date),700,240);text('Vehicle: '+(b.vehicleNumber||number(b.bike)||'—'),35,277);let bike=find('bikes',b.bike);text('Make / Model: '+[bike?.brand,bike?.model].filter(Boolean).join(' '),35,311);text('BILL TO',35,355,17,true,'#64748b');text(c?.name||b.customerName||b.walkin||'Walk-in Customer',35,387,23,true);text(c?.mobile||'',35,420,19);let y=460;x.fillStyle='#111827';x.fillRect(35,y,930,42);text('ITEM / DESCRIPTION',48,y+28,17,true,'white');text('QTY',540,y+28,17,true,'white');text('RATE',640,y+28,17,true,'white');text('AMOUNT',800,y+28,17,true,'white');y+=42;rows.forEach((r,i)=>{let lines=wrap(r.name,460);lines.forEach((line,j)=>text(line,48,y+32+j*27,20));text(r.qty,540,y+32,20);text(r.rate.toFixed(2),640,y+32,20);text(r.amount.toFixed(2),800,y+32,20);y+=heights[i];rule(y)});y+=38;for(let [label,value]of [['Labour',t.labour],['Parts',t.parts],['Service Discount',-splitDiscounts(b).service],['Parts Discount',-splitDiscounts(b).part],['Additional Discount',-Number(b.discount||0)],['Tax / Source Adjustment',t.tax],['TOTAL',t.total],['Received',paid(b)],['Balance',due(b)]]){text(label,540,y,20,label==='TOTAL');text('INR '+Number(value||0).toFixed(2),800,y,20,true);y+=35}rule(y);y+=34;text(db.settings.footer||'Thank you for your business.',35,y,18);text('Invoice copy generated from the saved record.',35,y+30,16,false,'#64748b');return canvas}
function canvasPng(canvas){return new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(Error('Unable to prepare receipt image')),'image/png'))}
const messageBeforeReceiptImage=messagePreview;
messagePreview=function(phone,message,bill){if(!bill)return messageBeforeReceiptImage(phone,message,bill);let b=find(bill.key,bill.id);if(!b)return;let n=whatsappNumber(phone),url=n?'https://wa.me/'+n+'?text='+encodeURIComponent(message):'';openModal('Send Job Card & Receipt to WhatsApp',`<div class="receiptSendInstructions">📌 <strong>Step 1:</strong> Click “Copy Receipt as Image” or “Copy & Open WhatsApp”.<br><strong>Step 2:</strong> In WhatsApp chat, press <strong>Ctrl + V</strong> to paste the receipt image. On a phone, touch and hold the message field and choose Paste.</div><div class="receiptSendActions"><button type="button" class="btn secondary" id="copyReceiptImage">Copy Receipt as Image</button><button type="button" class="btn success" id="copyOpenReceipt" ${n?'':'disabled'}>${whatsappIcon()} Copy & Open WhatsApp</button><button type="button" class="btn secondary" id="downloadReceiptPng">Download PNG</button></div><p id="receiptCopyStatus" role="status" style="padding:0 16px">${n?'The image is ready to preview. You choose when to send it in WhatsApp.':'Add a valid mobile number to the customer before opening WhatsApp.'}</p><div id="receiptImagePreview"></div><div class="formactions">${btn('Close','cancel','secondary')}${n?`<a class="btn success" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${whatsappIcon()} Open WhatsApp Only</a>`:''}</div>`);let canvas=receiptCanvas(bill.key,bill.id);canvas.setAttribute('aria-label','Invoice image preview');canvas.setAttribute('role','img');$('#receiptImagePreview').appendChild(canvas);let png=canvasPng(canvas);let status=$('#receiptCopyStatus');let copy=(open)=>{if(!navigator.clipboard?.write||typeof ClipboardItem==='undefined'){status.textContent='Image clipboard is unavailable in this browser. Download PNG, then attach it in WhatsApp.';return}let item;try{item=new ClipboardItem({'image/png':png})}catch{status.textContent='Image copying is unavailable. Use Download PNG.';return}navigator.clipboard.write([item]).then(()=>{status.textContent='Receipt image copied. Paste it in WhatsApp with Ctrl + V, then send.';if(open){let tab=window.open(url,'_blank','noopener,noreferrer');status.textContent+=' If WhatsApp did not open, click Open WhatsApp Only below.'}}).catch(()=>{status.textContent='Browser blocked copying the image. Use Download PNG and attach the image in WhatsApp.'})};$('#copyReceiptImage').onclick=()=>copy(false);$('#copyOpenReceipt').onclick=()=>copy(true);$('#downloadReceiptPng').onclick=async()=>{try{let blob=await png,href=URL.createObjectURL(blob),a=document.createElement('a');a.href=href;a.download='Receipt-'+b.id.replace(/[^a-z0-9_-]/gi,'-')+'.png';a.click();setTimeout(()=>URL.revokeObjectURL(href),10000);status.textContent='PNG prepared for download. Attach it in WhatsApp using its paperclip button.'}catch(err){status.textContent=err.message}}};
function validInvoiceImage(value){return typeof value==='string'&&/^data:image\/(png|jpeg|webp);base64,[A-Za-z0-9+/=]+$/.test(value)}
