const settingsBeforeInvoiceAssets=settingsPage;
settingsPage=function(){return settingsBeforeInvoiceAssets()+`<section class="panel"><div class="panelhead"><h2>UPI Scan Code & Invoice Stamp</h2></div><div class="panelbody"><form id="invoiceAssetSettings"><div class="formgrid">${field({key:'upiId',label:'Business UPI ID',placeholder:'yourbusiness@bank'},db.settings)}${field({key:'stampCaption',label:'Stamp / Signature Caption'}, {...db.settings,stampCaption:db.settings.stampCaption||'Authorized Signatory'})}</div><button type="submit" class="btn">Save Invoice Payment Details</button></form><p>Upload your payment provider’s QR image and your business stamp/signature. Images save immediately and appear on invoices and WhatsApp receipt images.</p><div class="invoiceAssetGrid">${[['upiQrImage','UPI Payment QR Code'],['stampImage','Stamp / Signature Image']].map(([key,label])=>`<section><h3>${label}</h3>${validInvoiceImage(db.settings[key])?`<img class="assetSettingsPreview" src="${db.settings[key]}" alt="${label}"><button type="button" class="btn danger small" data-remove-invoice-asset="${key}">Remove Image</button>`:'<p>No image uploaded.</p>'}<label class="field"><span>Upload PNG / JPG / WebP (maximum 1 MB)</span><input type="file" accept="image/png,image/jpeg,image/webp" capture="environment" data-invoice-asset="${key}"></label></section>`).join('')}</div></div></section>`};
const renderBeforeInvoiceAssets=render;
render=function(){renderBeforeInvoiceAssets();if(page!=='settings')return;if($('#invoiceAssetSettings'))$('#invoiceAssetSettings').onsubmit=e=>{e.preventDefault();let fields=new FormData(e.target),upi=String(fields.get('upiId')||'').trim();if(upi&&!/^[a-zA-Z0-9._-]+@[a-zA-Z0-9.-]+$/.test(upi))return toast('Enter a valid UPI ID, such as business@bank');let before=structuredClone(db.settings);db.settings.upiId=upi;db.settings.stampCaption=String(fields.get('stampCaption')||'').trim();if(save('Invoice payment details saved')===false)db.settings=before};for(let input of $$('[data-invoice-asset]'))input.onchange=async()=>{let file=input.files[0];if(!file)return;input.disabled=true;try{let image=await readAttachment(file);if(!validInvoiceImage(image.data))throw Error('Choose a PNG, JPG or WebP image');let key=input.dataset.invoiceAsset,before=db.settings[key];db.settings[key]=image.data;if(new Blob([JSON.stringify(db)]).size>4*1024*1024){db.settings[key]=before;throw Error('Browser storage limit reached. Remove unused attachments first.')}if(save('Invoice image saved')===false){db.settings[key]=before;return}render()}catch(err){toast(err.message)}finally{input.disabled=false}};for(let button of $$('[data-remove-invoice-asset]'))button.onclick=()=>{let key=button.dataset.removeInvoiceAsset,before=db.settings[key];delete db.settings[key];if(save('Invoice image removed')===false){db.settings[key]=before;return}render()}};
