/* Dedicated receipt layout sized in physical millimetres for browser printer drivers. */
function thermalReceiptMarkup(key,id,width){let b=find(key,id);if(!b)return '';let c=find('customers',b.customer),t=billTotals(b),s=db.settings;return `<article class="thermalInvoice" style="--receipt-width:${width}mm"><div class="thermalCenter"><h2>${esc(s.name)}</h2><p>${esc(s.address||'')}</p><p>${esc(s.phone||'')}</p>${s.gst&&invoiceTypeOf(b)==='gst'?`<p>GSTIN: ${esc(s.gst)}</p>`:''}<strong>${invoiceTypeOf(b)==='gst'?'GST INVOICE':'NON-GST INVOICE'}</strong></div><hr><p><strong>${esc(b.sourceId||b.id)}</strong><br>Date: ${esc(b.date)}<br>Customer: ${esc(c?.name||b.customerName||b.walkin||'Walk-in Customer')}${c?.mobile?'<br>Mobile: '+esc(c.mobile):''}${b.bike||b.vehicleNumber?'<br>Vehicle: '+esc(b.vehicleNumber||number(b.bike)):''}</p><hr><table class="thermalItems"><thead><tr><th>Item / Qty × Rate</th><th>Amount</th></tr></thead><tbody>${receiptRows(b).map(r=>`<tr><td>${esc(r.name)}<small>${r.qty} × ${Number(r.rate).toFixed(2)}</small></td><td>${Number(r.amount).toFixed(2)}</td></tr>`).join('')}</tbody></table><hr><dl>${[['Labour',t.labour],['Parts',t.parts],['Service Discount',-splitDiscounts(b).service],['Parts Discount',-splitDiscounts(b).part],['Additional Discount',-Number(b.discount||0)],['Tax / Adjustment',t.tax],['TOTAL',t.total],['Received',paid(b)],['BALANCE',due(b)]].map(([label,value])=>`<div class="${['TOTAL','BALANCE'].includes(label)?'thermalBold':''}"><dt>${label}</dt><dd>${Number(value||0).toFixed(2)}</dd></div>`).join('')}</dl><p class="thermalCenter">Amounts in INR</p>${validInvoiceImage(s.upiQrImage)?`<div class="thermalCenter"><img class="thermalQr" src="${s.upiQrImage}" alt="UPI scan code"><p>SCAN TO PAY</p></div>`:''}${s.upiId?`<p class="thermalCenter">UPI: ${esc(s.upiId)}</p>`:''}${validInvoiceImage(s.stampImage)?`<div class="thermalCenter"><img class="thermalStamp" src="${s.stampImage}" alt="Stamp / signature"><p>${esc(s.stampCaption||'Authorized Signatory')}</p></div>`:''}<hr><p class="thermalCenter">${esc(s.footer||'Thank you for your business.')}</p></article>`}
function openThermalInvoice(key,id,width){width=Number(width||db.settings.thermalWidth)===58?58:80;openModal('Thermal Invoice — '+width+' mm',`<div class="thermalControls"><label>Paper Width <select id="thermalPaperWidth"><option value="58" ${width===58?'selected':''}>58 mm</option><option value="80" ${width===80?'selected':''}>80 mm</option></select></label><p>Choose your thermal printer in the print window. Match its paper width, set scale to 100%, disable headers/footers and use no margins. Requires an installed printer driver.</p></div><div class="thermalPreview">${thermalReceiptMarkup(key,id,width)}</div><div class="formactions">${btn('Close','cancel','secondary')}<button type="button" class="btn" id="printThermalReceipt">${icon('print')}Print Thermal Receipt</button></div>`);$('#thermalPaperWidth').onchange=e=>openThermalInvoice(key,id,e.target.value);$('#printThermalReceipt').onclick=()=>{let style=document.createElement('style');style.id='thermalPageSize';style.textContent='@media print{@page{size:'+width+'mm auto;margin:0}}';document.head.appendChild(style);document.body.classList.add('printingThermal');let cleanup=()=>{document.body.classList.remove('printingThermal');style.remove();window.removeEventListener('afterprint',cleanup)};window.addEventListener('afterprint',cleanup);try{window.print()}catch{cleanup();toast('Open the browser print menu to print this receipt.')}}}
